window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9b493d79e1d2c6b5"]={"versions": [{"id": "FIG-9b493d79e1d2c6b5", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung einer Inter-ECU Sender-Receiver-Kommunikation für gequeute Daten (<code>isQueued = TRUE</code>, Ereignisverteilung). Es illustriert das Laufzeitverhalten bei nicht-blockierendem Empfang über einen <code>DataReceivePoint</code> (ohne verknüpften <code>WaitPoint</code>) sowie das Verhalten der RTE-Empfangs-API bei initial leerer Warteschlange.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten auf Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>Sender Application</code> (Software-Component auf Sender-ECU)</li>\n<li><code>Sender's RTE</code> (RTE der Sender-ECU)</li>\n<li><code>Sender's COM / Netwok / Receiver's COM</code> (zusammengefasste Repräsentation der Kommunikationsstapel beider ECUs inklusive Netzwerkübertragung)</li>\n<li><code>Receiver's RTE</code> (RTE der Empfänger-ECU)</li>\n<li><code>Receiver application</code> (Software-Component auf Empfänger-ECU)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>Rte_Send_p_e</code>: Expliziter Sendeaufruf der Sender-Applikation an die Sender-RTE (Rückgabewert: <code>RTE_E_OK</code>).</li>\n<li><code>Com_SendSignal</code>: Signalübertragungsaufruf von der Sender-RTE an die COM-Schicht (Rückgabewert: <code>E_OK</code>).</li>\n<li><code>Rte_COMCbk_&lt;sn&gt;</code>: COM-Empfangs-Callback zur Benachrichtigung der Receiver-RTE über neue Signaldaten.</li>\n<li><code>Com_ReceiveSignal</code>: Signalabruf durch die Receiver-RTE aus der COM-Schicht (Rückgabewert: <code>E_OK</code>).</li>\n<li><code>Rte_Receive_p_e</code>: Nicht-blockierender Empfangsaufruf der Receiver-Applikation an die Receiver-RTE (Rückgabewerte: <code>RTE_E_NO_DATA</code> bei leerer Queue, <code>RTE_E_OK</code> bei erfolgreichem Entnehmen).</li>\n<li>Konfigurationsparameter / Annotation: Port <code>p</code>, Datenelement <code>e</code>, <code>DataElementPrototype.isQueued = TRUE</code>, <code>DataSendPoint</code> auf Senderseite, <code>DataReceivePoint</code> auf Empfängerseite.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der zeitliche Ablauf gliedert sich in sechs durchnummerierte Phasen:</p>\n<ol class=\"fig-list\">\n<li><code>(1)</code> Initialisierung / Flush: Die RTE-Queue auf Empfängerseite für das Ereignis <code>p_e</code> wird initialisiert bzw. geleert.</li>\n<li><code>(2)</code> Abfrage bei leerer Queue: <code>Receiver application</code> ruft <code>Rte_Receive_p_e</code> auf. Da die Queue leer ist, kehrt der Aufruf unmittelbar mit <code>RTE_E_NO_DATA</code> zurück.</li>\n<li>Sendevorgang: <code>Sender Application</code> sendet ein Datenereignis via <code>Rte_Send_p_e</code> an <code>Sender's RTE</code>, welche <code>Com_SendSignal</code> aufruft (<code>E_OK</code>) und den Aufruf mit <code>RTE_E_OK</code> quittiert.</li>\n<li>Signalempfang und Enqueue: <code>Receiver's COM</code> ruft nach der Netzwerkübertragung den Callback <code>Rte_COMCbk_&lt;sn&gt;</code> der <code>Receiver's RTE</code> auf <code>(3)</code>. Die Receiver-RTE liest die Daten mittels <code>Com_ReceiveSignal</code> (<code>E_OK</code>) und reiht das empfangene Ereigniselement <code>e</code> in die RTE-Queue für Ereignis <code>e</code> ein <code>(4)</code>.</li>\n<li>Erfolgreicher Abruf: <code>Receiver application</code> ruft erneut <code>Rte_Receive_p_e</code> auf. Die Receiver-RTE entnimmt das Element aus der Queue und kopiert es in den OUT-Parameter <code>(5)</code>, woraufhin der Aufruf mit <code>RTE_E_OK</code> zurückkehrt.</li>\n<li><code>(6)</code> Das empfangene Ereigniselement steht der Empfängerapplikation im übergebenen OUT-Parameter zur Verfügung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Gequeute Kommunikation (<code>isQueued = TRUE</code>) puffert Ereignisse in einer FIFO-Warteschlange der RTE.</li>\n<li>Bei explizitem Empfang ohne verknüpften <code>WaitPoint</code> fungiert <code>Rte_Receive_&lt;p&gt;_&lt;o&gt;</code> als polling-fähige, nicht-blockierende Schnittstelle; ist kein Element vorhanden, wird zwingend <code>RTE_E_NO_DATA</code> zurückgegeben.</li>\n<li>Die Inter-ECU-Entkopplung erfolgt über COM-Callbacks (<code>Rte_COMCbk_&lt;sn&gt;</code>), welche die COM-Puffer in die applikative RTE-Warteschlange überführen.</li>\n<li>Rückgabewerte und Datentypen müssen dem RTE-Standard entsprechen (<code>RTE_E_OK</code>, <code>RTE_E_NO_DATA</code>, Signaltransfer via <code>E_OK</code>).</li>\n</ul>"}, {"id": "FIG-43f6eb1df2df7900", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung einer Inter-ECU Sender-Receiver-Kommunikation für gequeute Daten (<code>isQueued = TRUE</code>, Ereignisverteilung). Es illustriert das Laufzeitverhalten bei nicht-blockierendem Empfang über einen <code>DataReceivePoint</code> (ohne verknüpften <code>WaitPoint</code>) sowie das Verhalten der RTE-Empfangs-API bei initial leerer Warteschlange.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten auf Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>Sender Application</code> (Software-Component auf Sender-ECU)</li>\n<li><code>Sender's RTE</code> (RTE der Sender-ECU)</li>\n<li><code>Sender's COM / Netwok / Receiver's COM</code> (zusammengefasste Repräsentation der Kommunikationsstapel beider ECUs inklusive Netzwerkübertragung)</li>\n<li><code>Receiver's RTE</code> (RTE der Empfänger-ECU)</li>\n<li><code>Receiver application</code> (Software-Component auf Empfänger-ECU)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>Rte_Send_p_e</code>: Expliziter Sendeaufruf der Sender-Applikation an die Sender-RTE (Rückgabewert: <code>RTE_E_OK</code>).</li>\n<li><code>Com_SendSignal</code>: Signalübertragungsaufruf von der Sender-RTE an die COM-Schicht (Rückgabewert: <code>E_OK</code>).</li>\n<li><code>Rte_COMCbk_&lt;sn&gt;</code>: COM-Empfangs-Callback zur Benachrichtigung der Receiver-RTE über neue Signaldaten.</li>\n<li><code>Com_ReceiveSignal</code>: Signalabruf durch die Receiver-RTE aus der COM-Schicht (Rückgabewert: <code>E_OK</code>).</li>\n<li><code>Rte_Receive_p_e</code>: Nicht-blockierender Empfangsaufruf der Receiver-Applikation an die Receiver-RTE (Rückgabewerte: <code>RTE_E_NO_DATA</code> bei leerer Queue, <code>RTE_E_OK</code> bei erfolgreichem Entnehmen).</li>\n<li>Konfigurationsparameter / Annotation: Port <code>p</code>, Datenelement <code>e</code>, <code>DataElementPrototype.isQueued = TRUE</code>, <code>DataSendPoint</code> auf Senderseite, <code>DataReceivePoint</code> auf Empfängerseite.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der zeitliche Ablauf gliedert sich in sechs durchnummerierte Phasen:</p>\n<ol class=\"fig-list\">\n<li><code>(1)</code> Initialisierung / Flush: Die RTE-Queue auf Empfängerseite für das Ereignis <code>p_e</code> wird initialisiert bzw. geleert.</li>\n<li><code>(2)</code> Abfrage bei leerer Queue: <code>Receiver application</code> ruft <code>Rte_Receive_p_e</code> auf. Da die Queue leer ist, kehrt der Aufruf unmittelbar mit <code>RTE_E_NO_DATA</code> zurück.</li>\n<li>Sendevorgang: <code>Sender Application</code> sendet ein Datenereignis via <code>Rte_Send_p_e</code> an <code>Sender's RTE</code>, welche <code>Com_SendSignal</code> aufruft (<code>E_OK</code>) und den Aufruf mit <code>RTE_E_OK</code> quittiert.</li>\n<li>Signalempfang und Enqueue: <code>Receiver's COM</code> ruft nach der Netzwerkübertragung den Callback <code>Rte_COMCbk_&lt;sn&gt;</code> der <code>Receiver's RTE</code> auf <code>(3)</code>. Die Receiver-RTE liest die Daten mittels <code>Com_ReceiveSignal</code> (<code>E_OK</code>) und reiht das empfangene Ereigniselement <code>e</code> in die RTE-Queue für Ereignis <code>e</code> ein <code>(4)</code>.</li>\n<li>Erfolgreicher Abruf: <code>Receiver application</code> ruft erneut <code>Rte_Receive_p_e</code> auf. Die Receiver-RTE entnimmt das Element aus der Queue und kopiert es in den OUT-Parameter <code>(5)</code>, woraufhin der Aufruf mit <code>RTE_E_OK</code> zurückkehrt.</li>\n<li><code>(6)</code> Das empfangene Ereigniselement steht der Empfängerapplikation im übergebenen OUT-Parameter zur Verfügung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Gequeute Kommunikation (<code>isQueued = TRUE</code>) puffert Ereignisse in einer FIFO-Warteschlange der RTE.</li>\n<li>Bei explizitem Empfang ohne verknüpften <code>WaitPoint</code> fungiert <code>Rte_Receive_&lt;p&gt;_&lt;o&gt;</code> als polling-fähige, nicht-blockierende Schnittstelle; ist kein Element vorhanden, wird zwingend <code>RTE_E_NO_DATA</code> zurückgegeben.</li>\n<li>Die Inter-ECU-Entkopplung erfolgt über COM-Callbacks (<code>Rte_COMCbk_&lt;sn&gt;</code>), welche die COM-Puffer in die applikative RTE-Warteschlange überführen.</li>\n<li>Rückgabewerte und Datentypen müssen dem RTE-Standard entsprechen (<code>RTE_E_OK</code>, <code>RTE_E_NO_DATA</code>, Signaltransfer via <code>E_OK</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-9b493d79e1d2c6b5", "to": "FIG-43f6eb1df2df7900", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
